#include "../server/ferretdb_compat.h"
#include <assert.h>
#include <sqlite3.h>
#include <stdio.h>
static void fixture(const char*p,int index_format){sqlite3*d;char sql[1024];assert(sqlite3_open(p,&d)==SQLITE_OK);assert(sqlite3_exec(d,"CREATE TABLE _ferretdb_collections(name TEXT NOT NULL UNIQUE,table_name TEXT NOT NULL UNIQUE,settings TEXT NOT NULL) STRICT;CREATE TABLE boards_abcd(_ferretdb_sjson TEXT NOT NULL) STRICT;CREATE TABLE lists_abcd(_ferretdb_sjson TEXT NOT NULL) STRICT;CREATE TABLE swimlanes_abcd(_ferretdb_sjson TEXT NOT NULL) STRICT;CREATE TABLE cards_abcd(_ferretdb_sjson TEXT NOT NULL) STRICT;",NULL,NULL,NULL)==SQLITE_OK);sprintf(sql,"INSERT INTO _ferretdb_collections VALUES('boards','boards_abcd','{\"indexFormat\":%d}'),('lists','lists_abcd','{\"indexFormat\":%d}'),('swimlanes','swimlanes_abcd','{\"indexFormat\":%d}'),('cards','cards_abcd','{\"indexFormat\":%d}')",index_format,index_format,index_format,index_format);assert(sqlite3_exec(d,sql,NULL,NULL,NULL)==SQLITE_OK);sqlite3_close(d);}
int main(int ac,char**av){char good[512],unknown[512],broken[512];FILE*f;assert(ac==2||ac==3);sprintf(good,"%s/good.sqlite",av[1]);sprintf(unknown,"%s/unknown.sqlite",av[1]);sprintf(broken,"%s/broken.sqlite",av[1]);fixture(good,2);fixture(unknown,3);assert(wena_ferretdb_probe_readonly(good)==WENA_FERRET_V1_SJSON_INDEX2);assert(wena_ferretdb_probe_readonly(unknown)==WENA_FERRET_UNKNOWN);assert(wena_ferretdb_probe_readonly("relative.sqlite")==WENA_FERRET_UNKNOWN);f=fopen(broken,"wb");assert(f);fputs("not sqlite",f);fclose(f);assert(wena_ferretdb_probe_readonly(broken)==WENA_FERRET_UNKNOWN);if(ac==3)assert(wena_ferretdb_probe_readonly(av[2])==WENA_FERRET_V1_SJSON_INDEX2);return 0;}
